(7240449, 1121447, 61396, '<td valign="top">incomprehensible. well done.</td>', 'incomprehensible. well done.', '2014-07-13 11:09:46.000000', NULL, 1),
(7240476, 1121314, 100831, '<td valign="top">I''m enjoying the panoramic display .... and the way I can see through all the way through to the back of the fountain... yet the puddle in front with the reflection is great. Nicely done. Bump.</td>', 'I''m enjoying the panoramic display .... and the way I can see through all the way through to the back of the fountain... yet the puddle in front with the reflection is great. Nicely done. Bump.', '2014-07-13 12:10:16.000000', NULL, 1),
(7240478, 1120904, 100831, '<td valign="top">Some may say the horizon isn''t quite straight but we all know the earth isn''t straight either:) Besides, it''s always moving!!!! The colors here are fabulous. Love the reflection.  8</td>', 'Some may say the horizon isn''t quite straight but we all know the earth isn''t straight either:) Besides, it''s always moving!!!! The colors here are fabulous. Love the reflection.  8', '2014-07-13 12:13:11.000000', NULL, 1),
(7240479, 1121543, 100831, '<td valign="top">It''s funny how dof works... while i KNOW this water is moving, it almost appears stagnant because it''s so crisp. Well done fountain image. I like the toning.  I probably would have cropped a bit from the top to bring more attention to the reflection, but that''s just me. 7</td>', 'It''s funny how dof works... while i KNOW this water is moving, it almost appears stagnant because it''s so crisp. Well done fountain image. I like the toning.  I probably would have cropped a bit from the top to bring more attention to the reflection, but that''s just me. 7', '2014-07-13 12:16:32.000000', NULL, 1),
(7240481, 1121449, 100831, '<td valign="top">yup, life is always moving. Excellent image. Bump.</td>', 'yup, life is always moving. Excellent image. Bump.', '2014-07-13 12:17:47.000000', NULL, 1),
(7240482, 1121410, 100831, '<td valign="top">OK. I know this isn''t, but I''m going to say it''s a swimming pool and those are lane swimmers.. cautiously trying to make it to the other end.  Then I look at the title. Cause and effect... I see a man and his dog on the bottom right and some other alien like figures floating around.  Maybe we''re just watering time away. Or maybe the earth is melting... hahahaha. In the end why does it matter? Now you know why I like abstracts. I''m not sure I''d hang this one on my wall but it sure does make me think. 9</td>', 'OK. I know this isn''t, but I''m going to say it''s a swimming pool and those are lane swimmers.. cautiously trying to make it to the other end.  Then I look at the title. Cause and effect... I see a man and his dog on the bottom right and some other alien like figures floating around.  Maybe we''re just watering time away. Or maybe the earth is melting... hahahaha. In the end why does it matter? Now you know why I like abstracts. I''m not sure I''d hang this one on my wall but it sure does make me think. 9', '2014-07-13 12:25:30.000000', NULL, 1),
(7240484, 1121447, 100831, '<td valign="top">that''s too scary:) Great imagery though.</td>', 'that''s too scary:) Great imagery though.', '2014-07-13 12:26:45.000000', NULL, 1),
(7240485, 1121296, 100831, '<td valign="top">oh the delight. I can feel it. Love this.</td>', 'oh the delight. I can feel it. Love this.', '2014-07-13 12:27:38.000000', NULL, 1);
